#!/usr/bin/env python3
"""
Final Clinical Lab Data Harmonization Script
Complete unit harmonization with comprehensive conversion rules
"""

import pandas as pd
import numpy as np
import re

def clean_numeric_string(value):
    """Clean numeric strings by handling scientific notation and decimal commas"""
    if pd.isna(value) or value == '':
        return np.nan

    str_val = str(value).strip()
    str_val = str_val.replace(',', '.')
    str_val = str_val.strip('"').strip("'")

    return str_val

def convert_to_float(value):
    """Convert cleaned string to float"""
    if pd.isna(value) or value == '' or value is None:
        return np.nan

    try:
        return float(value)
    except (ValueError, TypeError):
        return np.nan

def convert_units_comprehensive(value, feature_name):
