            'default_range': (10, 35)
        },

        'Anion_Gap': {
            'rules': [],
            'default_range': (5, 25)
        },

        'Magnesium': {
            'rules': [
                (3.0, 2.43, 'multiply', (1.0, 3.0)),      # mmol/L to mg/dL
                (10.0, 2.43, 'multiply', (1.0, 3.0)),     # High mmol/L
            ],
            'default_range': (1.0, 3.0)
        },

        'Serum_Calcium': {
            'rules': [
                (3.0, 4.0, 'multiply', (6.0, 12.0)),      # mmol/L to mg/dL
                (5.0, 4.0, 'multiply', (6.0, 12.0)),      # mmol/L to mg/dL
            ],
            'default_range': (6.0, 12.0)
