        # Lipids
        'Total_Cholesterol': {
            'rules': [
                (15.0, 38.67, 'multiply', (50, 400)),     # mmol/L to mg/dL
                (20.0, 38.67, 'multiply', (50, 400)),     # mmol/L to mg/dL
            ],
            'default_range': (50, 400)
        },

        'LDL_Cholesterol': {
            'rules': [
                (8.0, 38.67, 'multiply', (10, 300)),       # mmol/L to mg/dL
            ],
            'default_range': (10, 300)
        },

        'HDL_Cholesterol': {
            'rules': [
                (3.0, 38.67, 'multiply', (10, 100)),       # mmol/L to mg/dL
            ],
